import csv
IN='/app/input'
press={}
with open(f'{IN}/press_profiles.csv') as f:
    for r in csv.DictReader(f):
        press[r['press_id']]={k:int(r[k]) for k in ['min_effective_dpi','max_tac_pct','max_spot_colors']}
sec={}
with open(f'{IN}/section_plan.csv') as f:
    for r in csv.DictReader(f):
        sec[r['section_id']]=r['press_id']
def b(v): return str(v).strip().lower()=='true'
pages=[]
with open(f'{IN}/kit_pages.csv') as f:
    for r in csv.DictReader(f): pages.append(r)
A='PRESS-OFFSET-A'; B='PRESS-DIGITAL-B'
def findings_for(p, pressid):
    pr=press[pressid]; f=[]
    eff=(int(p['artwork_dpi'])*100)//int(p['placed_scale_pct'])
    if eff<pr['min_effective_dpi']: f.append('DPI_TOO_LOW')
    margin=float(p['margin_in']); fb=b(p['full_bleed_design'])
    if not fb and margin<0.125: f.append('MARGIN_VIOLATION')
    bleed=float(p['bleed_in'])
    if fb and bleed<0.125: f.append('BLEED_SHORT')
    if int(p['ink_tac_pct'])>pr['max_tac_pct']: f.append('INK_OVER_LIMIT')
    if int(p['spot_colors'])>pr['max_spot_colors']: f.append('SPOT_UNSUPPORTED')
    if not b(p['fonts_embedded']): f.append('FONT_NOT_EMBEDDED')
    if int(p['element_count'])<int(p['min_element_required']): f.append('ELEMENT_COUNT_SHORT')
    return set(f)
press_rules={'DPI_TOO_LOW','INK_OVER_LIMIT','SPOT_UNSUPPORTED'}
print("=== Pages whose verdict (a press-dependent rule) flips if reassigned to the OTHER press ===")
for p in pages:
    cur=sec[p['section_id']]; other=B if cur==A else A
    fc=findings_for(p,cur); fo=findings_for(p,other)
    diff_press = (fc^fo)&press_rules
    if diff_press:
        direction='flagged->clean' if (fc-fo)&press_rules else 'clean->flagged'
        # which rules
        gained=fc-fo; lost=fo-fc
        print(f"{p['page_id']} sec={p['section_id']} on={cur}: cur_findings={sorted(fc)} ; on_other={sorted(fo)} ; press_rule_change={sorted(diff_press)} ({'would CLEAR on '+other if gained else 'would BREAK on '+other})")
PYEOF
python3 /tmp/opencode/flip.py
